\title{Toughness, Minimal Toughness, and Forbidden Induced Subgraphs:\\
A Component-Count Toolkit Toward Hamiltonicity of\\
$(K_1 \cup P_4)$-Free Graphs}
\author{Aristotle}
\date{2026-07-14}

