"""Demo: the component count numComp(G, S) and 1-toughness on small graphs."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Set, Tuple

Graph = Tuple[Set[int], Dict[int, Set[int]]]


def make_graph(n: int, edges: List[Tuple[int, int]]) -> Graph:
    verts: Set[int] = set(range(n))
    adj: Dict[int, Set[int]] = {v: set() for v in verts}
    for a, b in edges:
        adj[a].add(b); adj[b].add(a)
    return verts, adj


def components(graph: Graph, keep: Set[int]) -> int:
    _, adj = graph
    seen: Set[int] = set(); count = 0
    for s in keep:
        if s in seen:
            continue
        count += 1; stack = [s]; seen.add(s)
        while stack:
            v = stack.pop()
            for w in adj[v]:
                if w in keep and w not in seen:
                    seen.add(w); stack.append(w)
    return count


def num_comp(graph: Graph, delete: Set[int]) -> int:
    verts, _ = graph
    return components(graph, verts - delete)


def is_one_tough(graph: Graph) -> bool:
    verts, _ = graph
    if num_comp(graph, set()) != 1:
        return False
    for k in range(len(verts) + 1):
        for s in combinations(verts, k):
            c = num_comp(graph, set(s))
            if c >= 2 and c > len(s):
                return False
    return True


if __name__ == "__main__":
    c5 = make_graph(5, [(i, (i + 1) % 5) for i in range(5)])
    print("C_5 num_comp on deleting {0,2}:", num_comp(c5, {0, 2}))
    print("C_5 is 1-tough:", is_one_tough(c5))
    k4 = make_graph(4, list(combinations(range(4), 2)))
    print("K_4 is 1-tough:", is_one_tough(k4))

