from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Set, Tuple

Graph = Tuple[Set[int], Dict[int, Set[int]]]


def make_graph(n: int, edges: List[Tuple[int, int]]) -> Graph:
    adj: Dict[int, Set[int]] = {v: set() for v in range(n)}
    for a, b in edges:
        adj[a].add(b); adj[b].add(a)
    return set(range(n)), adj


def num_comp(graph: Graph, delete: Set[int]) -> int:
    verts, adj = graph
    keep = verts - delete
    seen: Set[int] = set(); count = 0
    for s in keep:
        if s in seen:
            continue
        count += 1; stack = [s]; seen.add(s)
        while stack:
            v = stack.pop()
            for w in adj[v]:
                if w in keep and w not in seen:
                    seen.add(w); stack.append(w)
    return count


def verify_monotone(sparse: Graph, dense: Graph) -> bool:
    """Assumes edges(sparse) subset edges(dense). Checks numComp(dense,S) <= numComp(sparse,S)."""
    n = len(sparse[0])
    for k in range(n + 1):
        for s in combinations(range(n), k):
            if num_comp(dense, set(s)) > num_comp(sparse, set(s)):
                return False
    return True


if __name__ == "__main__":
    n = 6
    c6 = make_graph(n, [(i, (i + 1) % n) for i in range(n)])
    k6 = make_graph(n, list(combinations(range(n), 2)))
    print("Monotone (C_6 <= K_6):", verify_monotone(c6, k6))
    print("Delete {0,3}: C_6 ->", num_comp(c6, {0, 3}), " K_6 ->", num_comp(k6, {0, 3}))

